/**
 * 额度占用流水：每一次预占、实占、释放逐层落记录（layer 字段），
 * 同一次业务动作在各约束层各留一条，保证多层额度可核对。
 */
@Entity
@Table(name = "limit_record")
public class LimitRecord {

    public enum Kind { PRE_OCCUPY, OCCUPY, RELEASE }

    public enum Reason { DRAWDOWN_ACCEPTED, DRAWDOWN_BOOKED, DRAWDOWN_FAILED, PRINCIPAL_REPAID }

    public enum Layer { TOTAL, PRODUCT, GROUP, GUARANTEE }

    @Id
    private String recordId;
    private String creditId;
    private Layer layer;
    private Kind kind;
    private Reason reason;
    private BigDecimal amount;
    private String productId;         // PRODUCT 层记录所属产品
    private String bizOrderNo;        // 关联业务单（提款 DD- 或还款 RP-）
    private String loanAccountNo;     // 关联借据（放款/还款恢复时有）
    private LocalDateTime createdAt;

/** 提款受理：逐层预占。任一层余量不足即整体拒绝。 */
@Transactional
public void preOccupy(String creditId, String bizOrderNo, String productId,
                      boolean productRequiresGuarantee, BigDecimal amount) {
    CreditLimit limit = get(creditId);
    if (availableForDrawdown(creditId, productId, productRequiresGuarantee).compareTo(amount) < 0) {
        throw new BizException(BizException.Code.LIMIT_INSUFFICIENT);
    }
    limit.setPreOccupied(limit.getPreOccupied().add(amount));
    record(creditId, LimitRecord.Layer.TOTAL, LimitRecord.Kind.PRE_OCCUPY,
            LimitRecord.Reason.DRAWDOWN_ACCEPTED, amount, null, bizOrderNo, null);

    findSubLimit(creditId, productId).ifPresent(sub -> {
        sub.setPreOccupied(sub.getPreOccupied().add(amount));
        record(creditId, LimitRecord.Layer.PRODUCT, LimitRecord.Kind.PRE_OCCUPY,
                LimitRecord.Reason.DRAWDOWN_ACCEPTED, amount, productId, bizOrderNo, null);
    });
    findGroupOf(creditId).ifPresent(group -> {
        group.setPreOccupied(group.getPreOccupied().add(amount));
        record(creditId, LimitRecord.Layer.GROUP, LimitRecord.Kind.PRE_OCCUPY,
                LimitRecord.Reason.DRAWDOWN_ACCEPTED, amount, null, bizOrderNo, null);
    });
    if (productRequiresGuarantee) {
        findCoverage(creditId).ifPresent(coverage -> {
            coverage.setPreOccupied(coverage.getPreOccupied().add(amount));
            record(creditId, LimitRecord.Layer.GUARANTEE, LimitRecord.Kind.PRE_OCCUPY,
                    LimitRecord.Reason.DRAWDOWN_ACCEPTED, amount, null, bizOrderNo, null);
        });
    }
}

/**
 * 付款结果落业务单。幂等：业务单已终态、或该结果已生效时，直接确认不产生任何新记录。
 */
@Transactional
public void onPaymentResult(DrawdownOrder order, String result) {
    if (order.terminal()) {
        return; // 幂等：终态后收到的任何结果只影响外部流水，不改业务单
    }
    order.setUpdatedAt(Ids.now());
    if ("SUCCESS".equals(result)) {
        if (order.getPaymentStatus() == DrawdownOrder.PaymentStatus.SUCCESS) {
            return; // 幂等：成功已受理过
        }
        order.setPaymentStatus(DrawdownOrder.PaymentStatus.SUCCESS);
        order.setStatus(DrawdownOrder.Status.EXTERNAL_SUCCESS_BOOKING_PENDING);
        order.setBookingStatus(DrawdownOrder.BookingStatus.TO_BOOK);
        book(order); // 同步尝试入账；失败转 RETRY_NEEDED 由补偿任务继续
    } else {
        if (order.getPaymentStatus() == DrawdownOrder.PaymentStatus.FAILED) {
            return;
        }
        order.setPaymentStatus(DrawdownOrder.PaymentStatus.FAILED);
        order.setStatus(DrawdownOrder.Status.FAILED);
        limitService.releasePreOccupied(order.getCreditId(), order.getBizOrderNo(), order.getProductId(),
                requiresGuarantee(order.getProductId()), order.getAmount());
    }
}

/**
 * 授信台账（总授信层）。多层额度见 ProductSubLimit / GroupLimit / GuaranteeCoverage，
 * 可用额度由 LimitService 按各层余量取最小值，层间不可相加替代。
 * restricted＝降额后占用高于新上限：保留实际占用，限制新增提款。
 */
@Entity
@Table(name = "credit_limit")
public class CreditLimit {

    @Id
    private String creditId;          // CR-开头，授信生效后由中台生成

    private String customerName;

    private BigDecimal totalLimit;    // 总授信上限
    private BigDecimal occupied;      // 实占：放款成功入账的本金
    private BigDecimal preOccupied;   // 预占：提款受理后、放款入账前
    private boolean frozen;           // 冻结：只影响新增提款资格，不减占用
    private boolean restricted;       // 降额导致占用高于上限：限制新增提款

    /** 总授信层余量；restricted 时下限取 0。 */

/**
 * 多层额度台账服务：总授信、产品子额度、集团限额、担保覆盖四层，可用额度取各层余量最小值。
 * 规则（docs/接口契约-阶段3.md §1）：
 * - 提款受理逐层预占；入账后逐层转实占；付款失败逐层释放；本金还款逐层恢复。
 * - 冻结：available 为 0，但恢复（占用减少）不受影响。
 * - restricted（降额占用超上限）：总授信层余量下限 0，只限制新增提款。
 * - 利息、费用不恢复任何层的占用。
 */
@Service
public class LimitService {

    private final CreditLimitRepository limitRepo;
    private final LimitRecordRepository recordRepo;
    private final ProductSubLimitRepository subLimitRepo;
    private final GroupLimitRepository groupRepo;
    private final GroupMemberRepository groupMemberRepo;
    private final GuaranteeCoverageRepository coverageRepo;

/**
 * 外部结果回调接收（模拟服务 → 中台）：付款、扣款、授信审批。
 * 幂等由各业务服务保证：终态业务单收到重复回调直接确认（DUPLICATE_CALLBACK 不改变状态）。
 * 回调成功只代表外部环节完成；提款是否成功以中台入账状态为准，授信是否生效以中台账本为准。
 */
@RestController
@RequestMapping("/middle/api/v1/callbacks")
public class ExternalResultController {

    private static final Logger log = LoggerFactory.getLogger(ExternalResultController.class);

    private final DrawdownOrderRepository drawdownRepo;
    private final RepaymentOrderRepository repayRepo;
    private final CreditApplicationRepository creditRepo;
    private final DrawdownService drawdownService;
    private final RepaymentService repaymentService;
    private final CreditService creditService;

/** 标识与通用常量。标识链见 docs/接口契约-阶段2.md §1：渠道申请号 → 中台业务单号 → 外部执行流水号。 */
public final class Ids {

    public static final String DATE_FMT = "yyyy-MM-dd";

get isAccountingAccrualBased(): boolean {
  return this.accountingRule() === 3 || this.accountingRule() === 4;
}

get isAccountingAccrualBased() {
  const accountingRule = this.loanProductAccountingForm.value.accountingRule;
  return accountingRule === 3 || accountingRule === 4;
}

/**
 * 提款业务单（阶段 2：单收款人，支付信息直接挂在本单上；阶段 4 多收款人引入 PaymentInstruction 子表，
 * 一个业务单对应多条支付指令、多个成功批次形成多笔借据）。
 * 状态机见 docs/接口契约-阶段2.md §2；"外部已付款成功、中台入账未完成"是显式可恢复状态。
 */
@Entity
@Table(name = "drawdown_order")
public class DrawdownOrder {

    public enum Status { PROCESSING, EXTERNAL_SUCCESS_BOOKING_PENDING, SUCCESS, FAILED, CANCELLED }

    /** 外部付款指令状态（本单一条指令）。 */
    public enum PaymentStatus { TO_SUBMIT, PROCESSING, SUCCESS, FAILED, RESULT_UNCONFIRMED }

    /** 中台入账（Fineract 放款登记）状态。 */
    public enum BookingStatus { NONE, TO_BOOK, BOOKED, RETRY_NEEDED }

    @Id
    private String bizOrderNo;
    private String creditId;
    private String quoteNo;
    private String productId;
    private BigDecimal amount;
    private String payeeName;
    private String payeeAccount;
    private String purpose;

    private Status status;

