private void resolve(ExtTransaction tx, String status) {
    tx.setStatus(status);
    tx.setResultResolved(true);
    tx.setFinishedAt(LocalDateTime.now().withNano(0));
    if (tx.getKind() == Kind.APPROVAL) {
        // 审批结论：成功=APPROVED（批准额度默认等于申请额度）；失败=REJECTED
        tx.setResultDetail("SUCCESS".equals(status) ? "APPROVED" : "REJECTED");
        if ("APPROVED".equals(tx.getResultDetail())) {
            tx.setResultAmount(tx.getAmount());
        }
    }
}

/** 授信审批：requestedLimit 为申请额度；同步场景立即返回受理或终态。 */
@PostMapping("/approvals")
public Map<String, Object> submitApproval(@RequestBody SubmitRequest request) {
    SimulatorService.SubmitResult result = service.submit(Kind.APPROVAL, request.bizOrderNo(),
            request.requestedLimit(), request.customerName(), null);
    return Map.of("extSerialNo", result.extSerialNo(), "status", result.status());
}

/** 查单：永远返回外部交易的真实状态（终态未产生则 PROCESSING）。审批类附带结论与批准额度。 */
@Transactional
public ExtTransaction query(String extSerialNo) {
    ExtTransaction tx = txRepo.findById(extSerialNo).orElseThrow();
    if (!tx.isResultResolved() && tx.getProcessDueAt() != null
            && LocalDateTime.now().withNano(0).isAfter(tx.getProcessDueAt())) {
        resolve(tx, tx.getScenario() == Scenario.ASYNC_FAIL ? "FAILED" : "SUCCESS");
    }
    return tx;
}

/** 查单收敛（补偿任务用）：审批受理超时后主动查审批结论。 */
@Transactional
public void queryAndSettle(CreditApplicationOrder order) {
    SimulatorClient.ExternalStatus status = simulator.query("APPROVAL", order.getApprovalExtSerialNo());
    if ("APPROVED".equals(status.result()) || "REJECTED".equals(status.result())) {
        onApprovalResult(order, status.result(), status.approvedLimit());
    }
}

/**
 * 授信申请单：初次授信、提额、降额、续授信都走申请＋外部审批；冻结/解冻是运营操作不走审批。
 * 审批通过后由中台按 type 生效（INITIAL 建授信＋各层配置；DECREASE 降额保留占用）。
 */
@Entity
@Table(name = "credit_application")
public class CreditApplicationOrder {

    public enum Status { PROCESSING, APPROVED, REJECTED }

    public enum Type { INITIAL, LIMIT_INCREASE, LIMIT_DECREASE, RENEWAL }

    @Id
    private String bizOrderNo;         // CR-开头
    private String customerName;
    private Type type;
    private String targetCreditId;     // 调整类申请的目标授信；INITIAL 为空
    private BigDecimal requestedLimit;

    // 各层配置随申请提交，审批通过后一并生效
    private String groupNo;
    private String productSubLimitsJson;
    private String guaranteeOrgName;
    private BigDecimal guaranteeCoverageLimit;
    private BigDecimal guaranteeCoverageRatio;

    private Status status;
    private String approvalExtSerialNo;
    private BigDecimal approvedLimit;  // 模拟审批返回的批准额度
    private String createdCreditId;    // INITIAL 生效后的授信号
    private LocalDateTime createdAt;
    private LocalDateTime updatedAt;

/**
 * 审批结果落申请单（回调与查单共用）。幂等：已终态的申请单收到重复结果直接忽略。
 * approvedLimit 为 null 时取申请额度（同步批准）；批准额度可能低于申请额度。
 */
@Transactional
public void onApprovalResult(CreditApplicationOrder order, String result, BigDecimal approvedLimit) {
    if (order.terminal()) {
        return;
    }
    order.setUpdatedAt(Ids.now());
    if ("APPROVED".equals(result)) {
        BigDecimal effective = approvedLimit == null ? order.getRequestedLimit() : approvedLimit;
        order.setApprovedLimit(effective);
        order.setStatus(CreditApplicationOrder.Status.APPROVED);
        effectuate(order);
    } else {
        order.setStatus(CreditApplicationOrder.Status.REJECTED);
    }
}

/**
 * 授信申请与调整编排：申请单 → 模拟审批（回调/查单）→ 中台生效。
 * 审批结果只是数据；额度生效、降额后保留占用、冻结状态全部由中台账本决定（边界设计 §6 判例）。
 * 冻结/解冻是运营操作，不走审批。
 */
@Service
public class CreditService {

    private static final Logger log = LoggerFactory.getLogger(CreditService.class);

    private final CreditApplicationRepository applicationRepo;
    private final CreditLimitRepository limitRepo;
    private final LimitService limitService;
    private final ProductSubLimitRepository subLimitRepo;
    private final GroupMemberRepository groupMemberRepo;
    private final GuaranteeCoverageRepository coverageRepo;
    private final SimulatorClient simulator;
    private final ObjectMapper objectMapper;

/**
 * 外部交易流水：付款（PAYMENT）与扣款（DEDUCTION）。
 * 状态：PROCESSING → SUCCESS | FAILED。回调未送达时中台查单也能取到真实终态（query 永远返回真实状态）。
 * 场景配置挂在 bizOrderNo 上，不混入正式业务字段（边界设计 §7）。
 */
@Entity
@Table(name = "ext_transaction")
public class ExtTransaction {

    public enum Kind { PAYMENT, DEDUCTION, APPROVAL }

    public enum Scenario {
        SYNC_SUCCESS, SYNC_REJECT, ASYNC_SUCCESS_DELAY, ASYNC_FAIL, NO_CALLBACK_NEED_QUERY
    }

    @Id
    private String extSerialNo;
    private Kind kind;
    private String bizOrderNo;
    private BigDecimal amount;
    private String accountName;     // 收款人/付款人
    private String accountNo;
    private String status;          // PROCESSING / SUCCESS / FAILED
    private Scenario scenario;
    private int delaySeconds;
    private LocalDateTime processDueAt;      // 异步结果的产生时间
    private boolean resultResolved;          // 终态是否已产生
    private boolean callbackSuppressed;      // NO_CALLBACK 场景：终态已产生但回调不投递
    private LocalDateTime finishedAt;
    private LocalDateTime createdAt;
    // 审批类交易（APPROVAL）专用：结论与批准额度
    private String resultDetail;    // APPROVED / REJECTED
    private BigDecimal resultAmount; // 批准额度（可能低于申请额度）

/** 审批查单：status 为受理状态，result 为审批结论（APPROVED/REJECTED），approvedLimit 为批准额度。 */
public record ExternalStatus(String extSerialNo, String status, String result,
                             BigDecimal approvedLimit, String finishedAt) {
}

/** 审批通过后的生效：INITIAL 建授信＋各层配置；INCREASE/DECREASE/RENEWAL 调整总授信（降额保留占用）。 */
@Transactional
public void effectuate(CreditApplicationOrder order) {
    BigDecimal limitAmount = order.getApprovedLimit();
    switch (order.getType()) {
        case INITIAL -> {
            CreditLimit limit = new CreditLimit();
            String creditId = Ids.next("CR-");
            limit.setCreditId(creditId);
            limit.setCustomerName(order.getCustomerName());
            limit.setTotalLimit(limitAmount);
            limit.setOccupied(BigDecimal.ZERO);
            limit.setPreOccupied(BigDecimal.ZERO);
            limit.setFrozen(false);
            limit.setRestricted(false);
            limitRepo.save(limit);
            order.setCreatedCreditId(creditId);
            applyLayers(order, creditId);
        }
        case LIMIT_INCREASE, RENEWAL -> {
            CreditLimit limit = requireCredit(order.getTargetCreditId());
            limit.setTotalLimit(limitAmount);
            limit.setRestricted(limit.getOccupied().add(limit.getPreOccupied()).compareTo(limitAmount) > 0);
            applyLayers(order, limit.getCreditId());
        }
        case LIMIT_DECREASE -> {
            CreditLimit limit = requireCredit(order.getTargetCreditId());
            limit.setTotalLimit(limitAmount);
            // 降额规则：占用高于新上限时保留实际占用、限制新增提款，不改已有债务
            limit.setRestricted(limit.getOccupied().add(limit.getPreOccupied()).compareTo(limitAmount) > 0);
        }
    }
}

/** 产品子额度层：单个授信在某产品下的额度上限（未配置的产品不参与约束）。 */
@Entity
@Table(name = "product_sub_limit")
public class ProductSubLimit {

    @Id
    private String subLimitId;
    private String creditId;
    private String productId;
    private BigDecimal subLimit;
    private BigDecimal occupied;
    private BigDecimal preOccupied;

/**
 * 外部结果回调接收（模拟服务 → 中台）：付款、扣款、授信审批。
 * 幂等由各业务服务保证：终态业务单收到重复回调直接确认（DUPLICATE_CALLBACK 不改变状态）。
 * 回调成功只代表外部环节完成；提款是否成功以中台入账状态为准，授信是否生效以中台账本为准。
 */
@RestController
@RequestMapping("/middle/api/v1/callbacks")
public class ExternalResultController {

    private static final Logger log = LoggerFactory.getLogger(ExternalResultController.class);

    private final DrawdownOrderRepository drawdownRepo;
    private final RepaymentOrderRepository repayRepo;
    private final CreditApplicationRepository creditRepo;
    private final DrawdownService drawdownService;
    private final RepaymentService repaymentService;
    private final CreditService creditService;

/**
 * 担保覆盖额度层：担保机构为该授信提供的覆盖额度与覆盖比例。
 * 担保可支持借款金额＝剩余担保覆盖额度 ÷ 担保覆盖比例，仅对"担保要求=开"的产品生效。
 * 担保责任的生命周期（申请/确认/代偿/解除）是阶段 4 计划；本层是额度约束的承载。
 */
@Entity
@Table(name = "guarantee_coverage")
public class GuaranteeCoverage {

    @Id
    private String coverageId;

/**
 * 还款编排：订单 → 模拟扣款 → 确认到账 → Fineract 还款入账 → 读取分配明细 → 按本金逐层恢复占用。
 * 规则（docs/三系统边界设计.md §6）：归还利息、费用不恢复本金授信额度；
 * 分配顺序由 Fineract 产品策略决定，中台只保存分配结果，不在多个系统重复判断分配。
 */
@Service
public class RepaymentService {

    private static final Logger log = LoggerFactory.getLogger(RepaymentService.class);

    private final RepaymentOrderRepository orderRepo;
    private final DrawdownOrderRepository drawdownRepo;
    private final LimitService limitService;
    private final ProductConfigRepository productRepo;
    private final FineractClient fineract;
    private final SimulatorClient simulator;

/**
 * Fineract REST 适配层：中台唯一允许触 Fineract 的模块（docs/三系统边界设计.md §5）。
 * 端点与命令语义对应 Fineract 1.14.0：LoansApiResource(/v1/loans)、LoanTransactionsApiResource(/v1/loans/{id}/transactions)。
 * 审批命令本设计不需要单独调用：中台创建借据即审批放款一体（受托支付成功才登记），
 * 因此创建时直接提交为经审批口径（submittedOnDate+approvedOnDate），放款在支付确认后执行。
 */
@Component
@EnableConfigurationProperties(FineractProperties.class)
public class FineractClient {

    private static final Logger log = LoggerFactory.getLogger(FineractClient.class);

    private final FineractProperties props;
    private final RestClient http;

/**
 * 中台产品配置（阶段 2：基础参数；阶段 3 增加版本快照，已签订业务按约定版本执行）。
 * terms/repaymentModes 用逗号分隔存储，避免为验证项目引入 JSON TypeHandler。
 */
@Entity
@Table(name = "product_config")
public class ProductConfig {

    @Id
    private String productId;            // 中台产品标识，如 LOAN-PURCHASE
    private String productName;
    private BigDecimal minAmount;
    private BigDecimal maxAmount;
    private String terms;                // 支持期限（月），逗号分隔
    private String repaymentModes;       // EQUAL_PRINCIPAL,EQUAL_INSTALLMENTS
    private BigDecimal annualInterestRate; // 模拟基础年利率（%）
    private boolean requiresGuarantee;   // 担保要求=开：借该产品必须消耗担保覆盖额度层
    private String fineractProductId;    // 对应 Fineract 贷款产品 id（fineract-adapter 映射用）

/** 还款订单：扣款执行与入账状态。分配明细来自 Fineract 还款交易（本金/利息/费用），中台保存分配结果用于额度恢复与核对。 */
@Entity
@Table(name = "repayment_order")
public class RepaymentOrder {

    public enum Status { PROCESSING, SUCCESS, FAILED }

    public enum Type { DUE, EARLY_PRINCIPAL, EARLY_SETTLE }

