/**
 * 提款编排：报价 → 申请（逐层预占+创建借据+提交付款）→ 结果确认 → 入账（Fineract 放款+逐层实占）。
 * 状态机与异常恢复语义见 docs/接口契约-阶段2.md §6；额度按多层口径校验与记账（接口契约-阶段3.md §1）。
 * 产品规则按报价绑定的版本快照执行（ProductConfigVersion），新配置只适用于新报价。
 */
@Service
public class DrawdownService {

    private static final Logger log = LoggerFactory.getLogger(DrawdownService.class);

    private final DrawdownQuoteRepository quoteRepo;
    private final DrawdownOrderRepository orderRepo;
    private final ProductConfigRepository productRepo;
    private final ProductConfigVersionRepository versionRepo;
    private final LimitService limitService;
    private final FineractClient fineract;
    private final SimulatorClient simulator;
    private final ObjectMapper objectMapper;

/**
 * 产品配置版本（不可变）：每次产品配置变化生成新版本行；报价快照绑定版本号，
 * 已确认的申请按约定版本执行，新配置只适用于新报价（边界设计 §9）。
 */
@Entity
@Table(name = "product_config_version")
public class ProductConfigVersion {

    @Id
    private String versionId;
    private String productId;
    private int version;
    private BigDecimal minAmount;
    private BigDecimal maxAmount;
    private String terms;
    private String repaymentModes;
    private BigDecimal annualInterestRate;
    private boolean requiresGuarantee;
    private String fineractProductId;
    private LocalDateTime effectiveAt;

/**
 * 阶段 3 种子数据（主场景 §八 的数字）：企业甲总授信 80 万、采购贷子额度 70 万、
 * 甲乙集团限额 60 万、担保机构丙覆盖 40 万（覆盖比例 80%）→ 担保要求=开的采购贷最多可借 50 万。
 * fineractProductId 对应 Fineract 租户库中预置的贷款产品，由业务验收线初始化（问答验证不依赖其真实存在）。
 */
@Bean
CommandLineRunner seed(CreditLimitRepository limits, ProductConfigRepository products,
                       ProductSubLimitRepository subLimits, GroupLimitRepository groups,
                       GroupMemberRepository members, GuaranteeCoverageRepository coverages,
                       ProductConfigVersionRepository versions) {
    return args -> {
        if (limits.findById("CR-202609010001").isEmpty()) {
            limits.save(credit("CR-202609010001", "企业甲", "800000"));
            limits.save(credit("CR-202609010002", "企业乙", "500000"));

            groups.save(group("G-202609001", "甲乙集团", "600000"));

            members.save(member("GM-001", "G-202609001", "CR-202609010001"));
            members.save(member("GM-002", "G-202609001", "CR-202609010002"));

            subLimits.save(subLimit("SL-001", "CR-202609010001", "LOAN-PURCHASE", "700000"));

            GuaranteeCoverage coverage = new GuaranteeCoverage();
            coverage.setCoverageId("GC-001");
            coverage.setCreditId("CR-202609010001");
            coverage.setOrgName("担保机构丙");
            coverage.setCoverageLimit(new BigDecimal("400000"));
            coverage.setOccupied(BigDecimal.ZERO);
            coverage.setPreOccupied(BigDecimal.ZERO);
            coverage.setCoverageRatio(new BigDecimal("0.8"));
            coverages.save(coverage);
            log.info("种子授信与多层额度已生成: CR-202609010001");
        }
        if (products.findAll().isEmpty()) {
            products.saveAll(List.of(
                    product("LOAN-TURNOVER", "周转贷", "10000", "500000", "1,3,6,12", "7.20", false, "1"),
                    // 采购贷担保要求=开（主场景配置）：借款需消耗担保覆盖额度层
                    product("LOAN-PURCHASE", "采购贷", "50000", "1000000", "3,6,12", "8.00", true, "2"),
                    product("LOAN-GUARANTEE", "担保经营贷", "100000", "3000000", "6,12,24", "7.50", true, "3")));
            versions.saveAll(List.of(
                    version(versions, "LOAN-TURNOVER", 1, "10000", "500000", "1,3,6,12", "7.20", false, "1"),
                    version(versions, "LOAN-PURCHASE", 1, "50000", "1000000", "3,6,12", "8.00", true, "2"),
                    version(versions, "LOAN-GUARANTEE", 1, "100000", "3000000", "6,12,24", "7.50", true, "3")));
        }
    };
}

/** 提款报价快照：金额、利率、试算结果在报价时固定，申请时按快照校验，不直接使用页面实时值。 */
@Entity
@Table(name = "drawdown_quote")
public class DrawdownQuote {

    public enum Status { UNUSED, USED, EXPIRED }

    @Id
    private String quoteNo;
    private String creditId;
    private String productId;
    private BigDecimal amount;
    private Integer termMonths;
    private String repaymentMode;
    private String firstRepaymentDate;
    private BigDecimal annualInterestRate;
    private String trialScheduleJson;   // 试算计划快照（来自 Fineract calculateLoanSchedule）
    private String productVersionId;    // 绑定的产品配置版本：申请按约定版本执行
    private LocalDateTime validUntil;
    private Status status;

/**
 * 模拟服务核心：只模拟执行、结果、回调与查单，不实现任何贷款业务规则。
 * 提交幂等：同一 bizOrderNo+kind 重复提交返回同一流水号与当前状态，不产生新流水。
 */
@Service
@EnableConfigurationProperties(SimulatorProps.class)
public class SimulatorService {

    private final ExtTransactionRepository txRepo;
    private final ScenarioConfigRepository scenarioRepo;
    private final CallbackLogRepository callbackRepo;
    private final SimulatorProps props;

/**
 * 授信申请入口（阶段 3）：渠道做准入（允许发起授信申请的渠道），透传到中台走外部审批。
 * 申请单同时保存渠道侧快照，便于追溯当时从哪个渠道、以什么条件发起。
 */
public Map<String, Object> applyCredit(String channelId, Map<String, Object> request) {
    if (!channelAllowsCredit(channelId)) {
        throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_ENTITY, "CHANNEL_CREDIT_NOT_OPEN");
    }
    Map<String, Object> applied = middle.applyCredit(request);
    String channelRefNo = nextRef();
    ChannelApplicationRecord record = new ChannelApplicationRecord();
    record.setChannelRefNo(channelRefNo);
    record.setChannelId(channelId);
    record.setBizType(BizType.CREDIT);
    record.setBizOrderNo(String.valueOf(applied.get("bizOrderNo")));
    record.setDisplayStatus("PROCESSING");
    record.setChannelRuleSnapshotJson("{\"channelId\":\"" + channelId + "\",\"entry\":\"credit-application\"}");
    record.setCreatedAt(LocalDateTime.now().withNano(0));
    record.setUpdatedAt(record.getCreatedAt());
    recordRepo.save(record);
    return Map.of("channelRefNo", channelRefNo,
            "bizOrderNo", applied.get("bizOrderNo"),
            "displayStatus", "PROCESSING");
}

/**
 * 中台产品配置（阶段 2：基础参数；阶段 3 增加版本快照，已签订业务按约定版本执行）。
 * terms/repaymentModes 用逗号分隔存储，避免为验证项目引入 JSON TypeHandler。
 */
@Entity
@Table(name = "product_config")
public class ProductConfig {

    @Id
    private String productId;            // 中台产品标识，如 LOAN-PURCHASE
    private String productName;

/**
 * 还款编排：订单 → 模拟扣款 → 确认到账 → Fineract 还款入账 → 读取分配明细 → 按本金逐层恢复占用。
 * 规则（docs/三系统边界设计.md §6）：归还利息、费用不恢复本金授信额度；
 * 分配顺序由 Fineract 产品策略决定，中台只保存分配结果，不在多个系统重复判断分配。
 */
@Service
public class RepaymentService {

    private static final Logger log = LoggerFactory.getLogger(RepaymentService.class);

    private final RepaymentOrderRepository orderRepo;
    private final DrawdownOrderRepository drawdownRepo;
    private final LimitService limitService;
    private final ProductConfigRepository productRepo;
    private final FineractClient fineract;
    private final SimulatorClient simulator;

/**
 * 担保覆盖额度层：担保机构为该授信提供的覆盖额度与覆盖比例。
 * 担保可支持借款金额＝剩余担保覆盖额度 ÷ 担保覆盖比例，仅对"担保要求=开"的产品生效。
 * 担保责任的生命周期（申请/确认/代偿/解除）是阶段 4 计划；本层是额度约束的承载。
 */
@Entity
@Table(name = "guarantee_coverage")
public class GuaranteeCoverage {

    @Id
    private String coverageId;
    private String creditId;
    private String orgName;
    private BigDecimal coverageLimit;
    private BigDecimal occupied;
    private BigDecimal preOccupied;
    private BigDecimal coverageRatio;   // 如 0.8 表示担保覆盖 80% 的敞口

    /** 该层允许的借款金额＝剩余覆盖 ÷ 覆盖比例。 */

/**
 * 阶段 3 种子数据（主场景 §八 的数字）：企业甲总授信 80 万、采购贷子额度 70 万、
 * 甲乙集团限额 60 万、担保机构丙覆盖 40 万（覆盖比例 80%）→ 担保要求=开的采购贷最多可借 50 万。
 * fineractProductId 对应 Fineract 租户库中预置的贷款产品，由业务验收线初始化（问答验证不依赖其真实存在）。
 */
@Bean
CommandLineRunner seed(CreditLimitRepository limits, ProductConfigRepository products,
                       ProductSubLimitRepository subLimits, GroupLimitRepository groups,
                       GroupMemberRepository members, GuaranteeCoverageRepository coverages,
                       ProductConfigVersionRepository versions) {
    return args -> {
        if (limits.findById("CR-202609010001").isEmpty()) {
            limits.save(credit("CR-202609010001", "企业甲", "800000"));
            limits.save(credit("CR-202609010002", "企业乙", "500000"));

            groups.save(group("G-202609001", "甲乙集团", "600000"));

            members.save(member("GM-001", "G-202609001", "CR-202609010001"));
            members.save(member("GM-002", "G-202609001", "CR-202609010002"));

            subLimits.save(subLimit("SL-001", "CR-202609010001", "LOAN-PURCHASE", "700000"));

            GuaranteeCoverage coverage = new GuaranteeCoverage();
            coverage.setCoverageId("GC-001");
            coverage.setCreditId("CR-202609010001");
            coverage.setOrgName("担保机构丙");
            coverage.setCoverageLimit(new BigDecimal("400000"));
            coverage.setOccupied(BigDecimal.ZERO);
            coverage.setPreOccupied(BigDecimal.ZERO);
            coverage.setCoverageRatio(new BigDecimal("0.8"));
            coverages.save(coverage);
            log.info("种子授信与多层额度已生成: CR-202609010001");
        }
        if (products.findAll().isEmpty()) {
            products.saveAll(List.of(
                    product("LOAN-TURNOVER", "周转贷", "10000", "500000", "1,3,6,12", "7.20", false, "1"),
                    // 采购贷担保要求=开（主场景配置）：借款需消耗担保覆盖额度层
                    product("LOAN-PURCHASE", "采购贷", "50000", "1000000", "3,6,12", "8.00", true, "2"),
                    product("LOAN-GUARANTEE", "担保经营贷", "100000", "3000000", "6,12,24", "7.50", true, "3")));
            versions.saveAll(List.of(
                    version(versions, "LOAN-TURNOVER", 1, "10000", "500000", "1,3,6,12", "7.20", false, "1"),
                    version(versions, "LOAN-PURCHASE", 1, "50000", "1000000", "3,6,12", "8.00", true, "2"),
                    version(versions, "LOAN-GUARANTEE", 1, "100000", "3000000", "6,12,24", "7.50", true, "3")));
        }
    };
}

public enum Code {
    QUOTE_EXPIRED("报价已过期，请重新试算"),
    AMOUNT_CHANGED_NEED_REQUOTE("报价条件已变化，需重新确认报价"),
    LIMIT_INSUFFICIENT("可用额度不足"),
    TERM_NOT_SUPPORTED("该产品不支持所选期限"),
    PRODUCT_NOT_OPEN("产品未开放"),
    DUPLICATE_CALLBACK("重复回调已幂等确认"),
    BOOKING_RETRY_EXHAUSTED("入账重试次数已用尽，需人工处理"),
    LOAN_NOT_FOUND("借据不存在"),
    SIMULATOR_ERROR("外部服务不可用");

    public final String message;

    Code(String message) {
        this.message = message;
    }
}

/**
 * 展示状态映射（契约 §2）：中台 PROCESSING / EXTERNAL_SUCCESS_BOOKING_PENDING 等处理中状态
 * 对外统一展示"PROCESSING"；成功与失败直传。映射关系保留在 record.middleRawStatus。
 */
private String displayOf(String middleStatus) {
    return switch (middleStatus) {
        case "SUCCESS", "FAILED" -> middleStatus;
        default -> "PROCESSING"; // PROCESSING / EXTERNAL_SUCCESS_BOOKING_PENDING / 其他处理中状态
    };
}

/** 业务异常与错误码。错误码契约见 docs/接口契约-阶段2.md §4。 */
public class BizException extends RuntimeException {

    public enum Code {
        QUOTE_EXPIRED("报价已过期，请重新试算"),
        AMOUNT_CHANGED_NEED_REQUOTE("报价条件已变化，需重新确认报价"),
        LIMIT_INSUFFICIENT("可用额度不足"),
        TERM_NOT_SUPPORTED("该产品不支持所选期限"),
        PRODUCT_NOT_OPEN("产品未开放"),
        DUPLICATE_CALLBACK("重复回调已幂等确认"),
        BOOKING_RETRY_EXHAUSTED("入账重试次数已用尽，需人工处理"),
        LOAN_NOT_FOUND("借据不存在"),
        SIMULATOR_ERROR("外部服务不可用");

        public final String message;

        Code(String message) {
