/**
 * 外部结果回调接收（模拟服务 → 中台）：付款、扣款、授信审批。
 * 幂等由各业务服务保证：终态业务单收到重复回调直接确认（DUPLICATE_CALLBACK 不改变状态）。
 * 回调成功只代表外部环节完成；提款是否成功以中台入账状态为准，授信是否生效以中台账本为准。
 */
@RestController
@RequestMapping("/middle/api/v1/callbacks")
public class ExternalResultController {

    private static final Logger log = LoggerFactory.getLogger(ExternalResultController.class);

    private final DrawdownOrderRepository drawdownRepo;
    private final RepaymentOrderRepository repayRepo;
    private final CreditApplicationRepository creditRepo;
    private final DrawdownService drawdownService;
    private final RepaymentService repaymentService;
    private final CreditService creditService;

/**
 * 担保覆盖额度层：担保机构为该授信提供的覆盖额度与覆盖比例。
 * 担保可支持借款金额＝剩余担保覆盖额度 ÷ 担保覆盖比例，仅对"担保要求=开"的产品生效。
 * 担保责任的生命周期（申请/确认/代偿/解除）是阶段 4 计划；本层是额度约束的承载。
 */
@Entity
@Table(name = "guarantee_coverage")
public class GuaranteeCoverage {

    @Id
    private String coverageId;
    private String creditId;
    private String orgName;
    private BigDecimal coverageLimit;
    private BigDecimal occupied;
    private BigDecimal preOccupied;
    private BigDecimal coverageRatio;   // 如 0.8 表示担保覆盖 80% 的敞口

    /** 该层允许的借款金额＝剩余覆盖 ÷ 覆盖比例。 */

/** 提前结清/部分还本试算：透传 Fineract calculatePrepayment 结果（金额构成见源码核查报告 §1）。 */
public Map<String, Object> prepaymentQuote(String loanAccountNo, String type, BigDecimal amount) {
    requireLoan(loanAccountNo);
    Map<String, Object> trial = fineract.calculatePrepayment(loanAccountNo, Ids.now().toLocalDate().toString());
    return Map.of("loanAccountNo", loanAccountNo, "type", type,
            "amount", amount == null ? trial.get("amount") : amount, "trial", trial);
}

/**
 * 提款业务单（阶段 2：单收款人，支付信息直接挂在本单上；阶段 4 多收款人引入 PaymentInstruction 子表，
 * 一个业务单对应多条支付指令、多个成功批次形成多笔借据）。
 * 状态机见 docs/接口契约-阶段2.md §2；"外部已付款成功、中台入账未完成"是显式可恢复状态。
 */
@Entity
@Table(name = "drawdown_order")
public class DrawdownOrder {

    public enum Status { PROCESSING, EXTERNAL_SUCCESS_BOOKING_PENDING, SUCCESS, FAILED, CANCELLED }

    /** 外部付款指令状态（本单一条指令）。 */
    public enum PaymentStatus { TO_SUBMIT, PROCESSING, SUCCESS, FAILED, RESULT_UNCONFIRMED }

    /** 中台入账（Fineract 放款登记）状态。 */
    public enum BookingStatus { NONE, TO_BOOK, BOOKED, RETRY_NEEDED }

    @Id
    private String bizOrderNo;
    private String creditId;
    private String quoteNo;
    private String productId;
    private BigDecimal amount;
    private String payeeName;
    private String payeeAccount;
    private String purpose;

    private Status status;
    private PaymentStatus paymentStatus;
    private String extSerialNo;
    private BookingStatus bookingStatus;
    private Integer bookingRetryCount;
    private String bookingLastError;
    private String loanAccountNo;       // Fineract 借据 id，创建成功即写入（放款前即存在）
    private BigDecimal bookedAmount;    // 实际入账金额
    private LocalDateTime createdAt;
    private LocalDateTime updatedAt;

/** 放款登记（command=disburse）。真实放款金额与放款日由此固定为借据起息依据。 */
public void disburseLoan(String loanAccountNo, BigDecimal amount) {
    http.post().uri(uri -> uri.path("/loans/{id}").queryParam("command", "disburse").build(loanAccountNo))
            .body(Map.of("transactionAmount", amount,
                    "note", "融商贷受托支付放款",
                    "dateFormat", Ids.DATE_FMT, "locale", "en"))
            .retrieve().toBodilessEntity();
}

@Scheduled(fixedDelayString = "${compensation.poll-interval-ms:15000}")
public void compensate() {
    // 提款：提交失败重试
    drawdownRepo.findByPaymentStatus(DrawdownOrder.PaymentStatus.TO_SUBMIT)
            .forEach(drawdownService::submitPayment);
    // 提款：受理超时主动查单
    LocalDateTime deadline = LocalDateTime.now().minus(Duration.ofSeconds(paymentQueryTimeoutSeconds));
    List<DrawdownOrder> pendingPayments = drawdownRepo.findByPaymentStatus(DrawdownOrder.PaymentStatus.PROCESSING);
    for (DrawdownOrder order : pendingPayments) {
        if (order.getUpdatedAt() != null && order.getUpdatedAt().isBefore(deadline)) {
            log.info("提款付款超时，主动查单: {}", order.getBizOrderNo());
            drawdownService.queryAndSettle(order);
        }
    }
    // 提款：入账未完成 → 重试（含"外部已成功、中台未入账"的可恢复状态）
    for (DrawdownOrder order : drawdownRepo.findByBookingStatus(DrawdownOrder.BookingStatus.TO_BOOK)) {
        drawdownService.book(order);
    }
    for (DrawdownOrder order : drawdownRepo.findByBookingStatus(DrawdownOrder.BookingStatus.RETRY_NEEDED)) {
        if (order.getBookingRetryCount() != null && order.getBookingRetryCount() < bookingRetryMax) {
            drawdownService.book(order);
        }
    }
    // 还款：同样的三条补偿线
    repayRepo.findByDeductionStatus(RepaymentOrder.DeductionStatus.TO_SUBMIT)
            .forEach(repaymentService::submitDeduction);
    for (RepaymentOrder order : repayRepo.findByDeductionStatus(RepaymentOrder.DeductionStatus.PROCESSING)) {
        if (order.getUpdatedAt() != null && order.getUpdatedAt().isBefore(deadline)) {
            log.info("还款扣款超时，主动查单: {}", order.getBizOrderNo());
            repaymentService.queryAndSettle(order);
        }
    }
    // 扣款成功但入账未完成的还款订单（PROCESSING 且扣款已 SUCCESS）

