 */
@Entity
@Table(name = "channel_product_rule")
public class ChannelProductRule {

    @Id
    private String ruleId;
    private String channelId;          // SELF_SERVICE / RM_ASSISTED
    private String productId;          // 中台产品标识
    private boolean enabled;
    private BigDecimal maxAmount;      // 渠道单笔上限（≤ 中台 maxAmount）
    private String allowedTerms;       // 渠道开放期限（中台 termList 的子集），逗号分隔

/**
 * 担保覆盖额度层：担保机构为该授信提供的覆盖额度与覆盖比例。
 * 担保可支持借款金额＝剩余担保覆盖额度 ÷ 担保覆盖比例，仅对"担保要求=开"的产品生效。
