 * - 利息、费用不恢复任何层的占用。
 */
@Service
public class LimitService {

    private final CreditLimitRepository limitRepo;
    private final LimitRecordRepository recordRepo;
    private final ProductSubLimitRepository subLimitRepo;
    private final GroupLimitRepository groupRepo;
    private final GroupMemberRepository groupMemberRepo;
