/**
 * 阶段 3 种子数据（主场景 §八 的数字）：企业甲总授信 80 万、采购贷子额度 70 万、
 * 甲乙集团限额 60 万、担保机构丙覆盖 40 万（覆盖比例 80%）→ 担保要求=开的采购贷最多可借 50 万。
 * fineractProductId 对应 Fineract 租户库中预置的贷款产品，由业务验收线初始化（问答验证不依赖其真实存在）。
 */
@Bean
CommandLineRunner seed(CreditLimitRepository limits, ProductConfigRepository products,
                       ProductSubLimitRepository subLimits, GroupLimitRepository groups,
                       GroupMemberRepository members, GuaranteeCoverageRepository coverages,
                       ProductConfigVersionRepository versions) {
    return args -> {
        if (limits.findById("CR-202609010001").isEmpty()) {
            limits.save(credit("CR-202609010001", "企业甲", "800000"));
            limits.save(credit("CR-202609010002", "企业乙", "500000"));

            groups.save(group("G-202609001", "甲乙集团", "600000"));

            members.save(member("GM-001", "G-202609001", "CR-202609010001"));
            members.save(member("GM-002", "G-202609001", "CR-202609010002"));

            subLimits.save(subLimit("SL-001", "CR-202609010001", "LOAN-PURCHASE", "700000"));

            GuaranteeCoverage coverage = new GuaranteeCoverage();
            coverage.setCoverageId("GC-001");
            coverage.setCreditId("CR-202609010001");
            coverage.setOrgName("担保机构丙");
            coverage.setCoverageLimit(new BigDecimal("400000"));
            coverage.setOccupied(BigDecimal.ZERO);
            coverage.setPreOccupied(BigDecimal.ZERO);
            coverage.setCoverageRatio(new BigDecimal("0.8"));
            coverages.save(coverage);
            log.info("种子授信与多层额度已生成: CR-202609010001");
        }
        if (products.findAll().isEmpty()) {
            products.saveAll(List.of(
                    product("LOAN-TURNOVER", "周转贷", "10000", "500000", "1,3,6,12", "7.20", false, "1"),
                    // 采购贷担保要求=开（主场景配置）：借款需消耗担保覆盖额度层
                    product("LOAN-PURCHASE", "采购贷", "50000", "1000000", "3,6,12", "8.00", true, "2"),
                    product("LOAN-GUARANTEE", "担保经营贷", "100000", "3000000", "6,12,24", "7.50", true, "3")));
            versions.saveAll(List.of(
                    version(versions, "LOAN-TURNOVER", 1, "10000", "500000", "1,3,6,12", "7.20", false, "1"),
                    version(versions, "LOAN-PURCHASE", 1, "50000", "1000000", "3,6,12", "8.00", true, "2"),
                    version(versions, "LOAN-GUARANTEE", 1, "100000", "3000000", "6,12,24", "7.50", true, "3")));
        }
    };
}

/**
 * 授信台账（总授信层）。多层额度见 ProductSubLimit / GroupLimit / GuaranteeCoverage，
 * 可用额度由 LimitService 按各层余量取最小值，层间不可相加替代。
 * restricted＝降额后占用高于新上限：保留实际占用，限制新增提款。
 */
@Entity
@Table(name = "credit_limit")
public class CreditLimit {

    @Id
    private String creditId;          // CR-开头，授信生效后由中台生成

    private String customerName;

    private BigDecimal totalLimit;    // 总授信上限
    private BigDecimal occupied;      // 实占：放款成功入账的本金
    private BigDecimal preOccupied;   // 预占：提款受理后、放款入账前
    private boolean frozen;           // 冻结：只影响新增提款资格，不减占用
    private boolean restricted;       // 降额导致占用高于上限：限制新增提款

    /** 总授信层余量；restricted 时下限取 0。 */

/** 各层余量与最终可用额度（四层取最小）。 */
@GetMapping("/{creditId}/limits")
public Map<String, Object> limits(@PathVariable String creditId,
                                  @RequestParam(required = false) String productId,
                                  @RequestParam(required = false, defaultValue = "false") boolean requiresGuarantee) {
    var limit = limitService.get(creditId);
    return Map.of("creditId", creditId, "frozen", limit.isFrozen(), "restricted", limit.isRestricted(),
            "layers", limitService.layerView(creditId, productId),
            "available", limitService.availableForDrawdown(creditId, productId, requiresGuarantee));
}

/**
 * 多层额度台账服务：总授信、产品子额度、集团限额、担保覆盖四层，可用额度取各层余量最小值。
 * 规则（docs/接口契约-阶段3.md §1）：
 * - 提款受理逐层预占；入账后逐层转实占；付款失败逐层释放；本金还款逐层恢复。
 * - 冻结：available 为 0，但恢复（占用减少）不受影响。
 * - restricted（降额占用超上限）：总授信层余量下限 0，只限制新增提款。
 * - 利息、费用不恢复任何层的占用。
 */
@Service
public class LimitService {

    private final CreditLimitRepository limitRepo;
    private final LimitRecordRepository recordRepo;
    private final ProductSubLimitRepository subLimitRepo;
    private final GroupLimitRepository groupRepo;
    private final GroupMemberRepository groupMemberRepo;
    private final GuaranteeCoverageRepository coverageRepo;

/** 新增提款的最终可用额度：冻结为 0；否则各层余量取最小值。 */
public BigDecimal availableForDrawdown(String creditId, String productId, boolean productRequiresGuarantee) {
    CreditLimit limit = get(creditId);
    if (limit.isFrozen()) {
        return BigDecimal.ZERO;
    }
    BigDecimal available = limit.totalRemaining();
    Optional<ProductSubLimit> sub = findSubLimit(creditId, productId);
    if (sub.isPresent()) {
        available = available.min(sub.get().remaining());
    }
    Optional<GroupLimit> group = findGroupOf(creditId);
    if (group.isPresent()) {
        available = available.min(group.get().remaining());
    }
    if (productRequiresGuarantee) {
        Optional<GuaranteeCoverage> coverage = findCoverage(creditId);
        if (coverage.isEmpty()) {
            return BigDecimal.ZERO; // 担保要求=开 但无有效担保覆盖，不可借
        }
        available = available.min(coverage.get().supportable());
    }
    return available.max(BigDecimal.ZERO);
}

/**
 * 担保覆盖额度层：担保机构为该授信提供的覆盖额度与覆盖比例。
 * 担保可支持借款金额＝剩余担保覆盖额度 ÷ 担保覆盖比例，仅对"担保要求=开"的产品生效。
 * 担保责任的生命周期（申请/确认/代偿/解除）是阶段 4 计划；本层是额度约束的承载。
 */
@Entity
@Table(name = "guarantee_coverage")
public class GuaranteeCoverage {

    @Id
    private String coverageId;
    private String creditId;
    private String orgName;
    private BigDecimal coverageLimit;
    private BigDecimal occupied;
    private BigDecimal preOccupied;
    private BigDecimal coverageRatio;   // 如 0.8 表示担保覆盖 80% 的敞口

    /** 该层允许的借款金额＝剩余覆盖 ÷ 覆盖比例。 */

/** 总授信层余量；restricted 时下限取 0。 */
public BigDecimal totalRemaining() {
    BigDecimal remaining = totalLimit.subtract(occupied).subtract(preOccupied);
    return restricted ? remaining.max(BigDecimal.ZERO) : remaining;
}

/**
 * 授信申请与调整编排：申请单 → 模拟审批（回调/查单）→ 中台生效。
 * 审批结果只是数据；额度生效、降额后保留占用、冻结状态全部由中台账本决定（边界设计 §6 判例）。
 * 冻结/解冻是运营操作，不走审批。
 */
@Service
public class CreditService {

    private static final Logger log = LoggerFactory.getLogger(CreditService.class);

    private final CreditApplicationRepository applicationRepo;
    private final CreditLimitRepository limitRepo;
    private final LimitService limitService;
    private final ProductSubLimitRepository subLimitRepo;
    private final GroupMemberRepository groupMemberRepo;
    private final GuaranteeCoverageRepository coverageRepo;
    private final SimulatorClient simulator;
    private final ObjectMapper objectMapper;

@GetMapping("/options")
public Map<String, Object> options(@RequestParam String creditId) {
    limitService.get(creditId);
    List<Map<String, Object>> products = productRepo.findAll().stream()
            .map(p -> Map.<String, Object>of(
                    "productId", p.getProductId(),
                    "productName", p.getProductName(),
                    "minAmount", p.getMinAmount(),
                    "maxAmount", p.getMaxAmount(),
                    "terms", p.termList(),
                    "repaymentModes", p.repaymentModeList(),
                    // 多层口径：各约束层余量取最小值（总授信/产品子额度/集团限额/担保覆盖）
                    "availableAmount", limitService.availableForDrawdown(creditId, p.getProductId(), p.isRequiresGuarantee())))
